## GoldenMasterSupport.java

```java
package com.example.freight.golden;

import com.fasterxml.jackson.core.util.DefaultIndenter;
import com.fasterxml.jackson.core.util.DefaultPrettyPrinter;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Stream;

final class GoldenMasterSupport {

    /**
     * 录制时规整掉的易变字段。这份清单必须和录制端用的是同一份 —— 要么这个类被录制工具复用，
     * 要么录制工具搬进来调 scrub()。两边各写一份迟早会漂。
     */
    static final Set<String> VOLATILE_FIELDS = Set.of("traceId", "calcTime");

    static final ObjectMapper MAPPER = new ObjectMapper();

    /** 固定缩进和 \n 换行，不吃平台默认的 line.separator（Windows 上会变 \r\n）。 */
    private static final ObjectWriter CANONICAL_WRITER = MAPPER.writer(
            new DefaultPrettyPrinter()
                    .withObjectIndenter(new DefaultIndenter("  ", "\n"))
                    .withArrayIndenter(new DefaultIndenter("  ", "\n")));

    static final Path REPO_ROOT = locateRepoRoot();
    static final Path SAMPLE_DIR = REPO_ROOT.resolve("samples").resolve("freight");
    static final Path ACTUAL_DIR = REPO_ROOT.resolve("build").resolve("golden-master").resolve("actual");

    private GoldenMasterSupport() {
    }

    /** 从 user.dir 向上找到含 samples/freight 的目录，单模块多模块都能跑。 */
    private static Path locateRepoRoot() {
        Path dir = Paths.get(System.getProperty("user.dir")).toAbsolutePath();
        for (Path p = dir; p != null; p = p.getParent()) {
            if (Files.isDirectory(p.resolve("samples").resolve("freight"))) {
                return p;
            }
        }
        throw new IllegalStateException("找不到 samples/freight，起点：" + dir);
    }

    static List<SampleCase> allSamples() {
        try (Stream<Path> files = Files.list(SAMPLE_DIR)) {
            List<SampleCase> cases = new ArrayList<>();
            files.filter(p -> p.getFileName().toString().endsWith(".request.json"))
                    .sorted()
                    .forEach(p -> {
                        String fileName = p.getFileName().toString();
                        String name = fileName.substring(0, fileName.length() - ".request.json".length());
                        Path approved = SAMPLE_DIR.resolve(name + ".approved.json");
                        cases.add(new SampleCase(name, p,
                                Files.exists(approved) ? approved : null));
                    });
            return cases;
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static List<SampleCase> samplesWithApproved() {
        List<SampleCase> cases = new ArrayList<>();
        for (SampleCase c : allSamples()) {
            if (c.hasApproved()) {
                cases.add(c);
            }
        }
        return cases;
    }

    static SampleCase sample(String name) {
        return allSamples().stream()
                .filter(c -> c.name().equals(name))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("没有这条样本：" + name));
    }

    static JsonNode readJson(Path path) {
        try {
            return MAPPER.readTree(Files.readString(path, StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException("读不了 " + path, e);
        }
    }

    /** 递归剔掉易变字段，和录制端同一套规则。 */
    static JsonNode scrub(JsonNode node) {
        if (node.isObject()) {
            ObjectNode out = MAPPER.createObjectNode();
            node.fields().forEachRemaining(entry -> {
                if (!VOLATILE_FIELDS.contains(entry.getKey())) {
                    out.set(entry.getKey(), scrub(entry.getValue()));
                }
            });
            return out;
        }
        if (node.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            node.forEach(child -> out.add(scrub(child)));
            return out;
        }
        return node.deepCopy();
    }

    /**
     * 两边都过这一个函数再比字符串。
     * 真·原始字节比对会被 key 顺序、缩进、BOM 这类无意义差异搞红，
     * 所以规矩是：母版和实际值走同一个确定性写出器，然后字符串全等。
     * 数组顺序有语义（items 的明细顺序），不排序。
     */
    static String canonical(JsonNode node) {
        try {
            return CANONICAL_WRITER.writeValueAsString(sortKeys(node));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static JsonNode sortKeys(JsonNode node) {
        if (node.isObject()) {
            List<String> names = new ArrayList<>();
            node.fieldNames().forEachRemaining(names::add);
            Collections.sort(names);
            ObjectNode out = MAPPER.createObjectNode();
            for (String name : names) {
                out.set(name, sortKeys(node.get(name)));
            }
            return out;
        }
        if (node.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            node.forEach(child -> out.add(sortKeys(child)));
            return out;
        }
        return node.deepCopy();
    }

    /** 比对结果落盘，方便贴进 PR、或者确认无误后直接覆盖成新母版。 */
    static Optional<Path> writeActual(String name, String canonicalActual) {
        try {
            Files.createDirectories(ACTUAL_DIR);
            Path out = ACTUAL_DIR.resolve(name + ".actual.json");
            Files.writeString(out, canonicalActual, StandardCharsets.UTF_8);
            return Optional.of(out);
        } catch (IOException e) {
            return Optional.empty();
        }
    }
}
```

