## JsonNormalizer.java

```java
package com.example.freight.golden;

import com.fasterxml.jackson.core.util.DefaultIndenter;
import com.fasterxml.jackson.core.util.DefaultPrettyPrinter;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.ObjectWriter;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * 把 JSON 规整成可逐字符比对的形式:剔除易变字段(scrubbing)+ 固定 key 顺序/缩进/换行。
 * 两侧(approved 文件 与 实际返回)都过同一个 normalize,格式差异不会误报。
 */
final class JsonNormalizer {

    /**
     * 录样本时已经规整掉的易变字段。实际调用的返回值里仍然有,比对前要同样剔除。
     * 注意:这里是按字段名递归剔除,嵌套层里的同名字段也会被去掉。
     */
    private static final Set<String> VOLATILE_FIELDS = Set.of("traceId", "calcTime");

    private static final ObjectMapper MAPPER = JsonMapper.builder().build();

    /**
     * 显式指定换行为 "\n"。DefaultPrettyPrinter 默认用 System.lineSeparator(),
     * 在 Windows 上会写出 \r\n,导致 received 文件跨平台 diff 不稳。
     * 字段分隔符保持 Jackson 默认的 " : ",只要两侧同一个 printer 就一致。
     */
    private static final ObjectWriter WRITER = MAPPER.writer(prettyPrinter());

    private JsonNormalizer() {}

    static String normalize(JsonNode node) {
        try {
            return WRITER.writeValueAsString(canonicalize(node)) + "\n";
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static String normalize(String rawJson) {
        return normalize(parse(rawJson));
    }

    static JsonNode parse(String rawJson) {
        try {
            return MAPPER.readTree(rawJson);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static <T> T read(String rawJson, Class<T> type) {
        try {
            return MAPPER.readValue(rawJson, type);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static JsonNode toTree(Object value) {
        return MAPPER.valueToTree(value);
    }

    /**
     * 递归:object 按 key 排序并剔除易变字段;array 保持原顺序(items 的顺序有业务语义)。
     * 这里手工排序,是因为 SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS 只作用于 Map 序列化,
     * 对 ObjectNode 不生效(ObjectNode 自己按内部 LinkedHashMap 顺序输出)。
     */
    private static JsonNode canonicalize(JsonNode node) {
        if (node.isObject()) {
            List<String> names = new ArrayList<>();
            node.fieldNames().forEachRemaining(names::add);
            Collections.sort(names);
            ObjectNode out = MAPPER.createObjectNode();
            for (String name : names) {
                if (VOLATILE_FIELDS.contains(name)) {
                    continue;
                }
                out.set(name, canonicalize(node.get(name)));
            }
            return out;
        }
        if (node.isArray()) {
            ArrayNode out = MAPPER.createArrayNode();
            for (JsonNode element : node) {
                out.add(canonicalize(element));
            }
            return out;
        }
        return node.deepCopy();
    }

    private static DefaultPrettyPrinter prettyPrinter() {
        DefaultIndenter indenter = new DefaultIndenter("  ", "\n");
        DefaultPrettyPrinter printer = new DefaultPrettyPrinter();
        printer.indentObjectsWith(indenter);
        printer.indentArraysWith(indenter);
        return printer;
    }
}
