package com.example.freight.golden;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/** samples/freight 的扫描与读写。 */
final class SampleRepo {

    private static final String REQUEST_SUFFIX = ".request.json";
    private static final String DIR_PROPERTY = "freight.samples.dir";

    /**
     * 待批准清单:已录了 request、但还不能有 approved 的样本。
     *
     * 首重续重-新疆-vip —— 新类别(模板 1032 配了偏远省份表,新疆命中)。
     * 它是新路径,没有改动前的输出可以当基线;approved 值不能由程序输出生成。
     * 需求翻译的例子只给了 fee=26,items 明细待人工确认,见同目录的 PENDING.md。
     * 现由 FreightRemoteSurchargeTest 覆盖。确认 items 后:
     *   把 .received.json 改名为 .approved.json,并从本清单删除(否则守卫测试会红)。
     */
    static final Set<String> PENDING_APPROVAL = Set.of("首重续重-新疆-vip");

    private SampleRepo() {}

    /** 从工作目录逐级向上找 samples/freight,兼容单模块与多模块的不同 user.dir。 */
    static Path dir() {
        String override = System.getProperty(DIR_PROPERTY);
        if (override != null) {
            return Paths.get(override);
        }
        Path current = Paths.get("").toAbsolutePath();
        for (int i = 0; i < 6 && current != null; i++, current = current.getParent()) {
            Path candidate = current.resolve("samples").resolve("freight");
            if (Files.isDirectory(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException(
                "找不到 samples/freight,可用 -D" + DIR_PROPERTY + "=<绝对路径> 指定");
    }

    /** 所有录过 request 的样本名,按名字排序,保证用例顺序稳定。 */
    static List<String> allSampleNames() {
        try (Stream<Path> files = Files.list(dir())) {
            return files.map(p -> p.getFileName().toString())
                    .filter(n -> n.endsWith(REQUEST_SUFFIX))
                    .map(n -> n.substring(0, n.length() - REQUEST_SUFFIX.length()))
                    .sorted()
                    .collect(Collectors.toList());
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** 参与 golden master 回放的样本 = 全部样本 - 待批准。 */
    static List<String> approvedSampleNames() {
        return allSampleNames().stream()
                .filter(n -> !PENDING_APPROVAL.contains(n))
                .collect(Collectors.toList());
    }

    static Path request(String name)  { return dir().resolve(name + REQUEST_SUFFIX); }
    static Path approved(String name) { return dir().resolve(name + ".approved.json"); }
    static Path received(String name) { return dir().resolve(name + ".received.json"); }

    static String readUtf8(Path path) {
        try {
            return Files.readString(path, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException("读不到样本文件:" + path, e);
        }
    }

    static void writeUtf8(Path path, String content) {
        try {
            Files.writeString(path, content, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException("写不了文件:" + path, e);
        }
    }

    static void deleteReceived(String name) {
        try {
            Files.deleteIfExists(received(name));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
