package com.example.freight.golden;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.nio.file.Files;
import java.util.List;
import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 运费回放比对(golden master / characterization test)。
 *
 * 作用边界:它只证明「老路径的行为没有被偏远附加改动带偏」,不证明结果在业务上是对的。
 * 覆盖到的两条老路径:
 *   - 首重续重-广东  模板 1032 配了偏远表,但广东不在表中 → 应走老路径
 *   - 首重-北京-cod  模板 2001 没配偏远表            → 应走老路径
 */
@DisplayName("运费回放比对(golden master)")
class FreightGoldenMasterTest {

    @DisplayName("已批准样本:回放结果必须与 approved 一致")
    @ParameterizedTest(name = "{0}")
    @MethodSource("approvedSamples")
    void replayMatchesApproved(String name) {
        String actual = JsonNormalizer.normalize(FreightCalcHarness.replaySample(name));
        String expected = JsonNormalizer.normalize(SampleRepo.readUtf8(SampleRepo.approved(name)));

        if (expected.equals(actual)) {
            SampleRepo.deleteReceived(name);   // 修好之后清掉上次失败留下的残留
        } else {
            SampleRepo.writeUtf8(SampleRepo.received(name), actual);
        }

        assertEquals(expected, actual, () -> String.format(
                "样本【%s】的回放结果变了。实际输出已写到 %s。%n"
              + "先判断这是 bug 还是有意的行为变更;确认是有意变更再覆盖 approved 文件。",
                name, SampleRepo.received(name)));
    }

    static Stream<String> approvedSamples() {
        return SampleRepo.approvedSampleNames().stream();
    }

    // ---- 守卫测试:防止 golden master 集合被悄悄掏空或长期挂账 ----

    @Test
    @DisplayName("守卫:每个 request 要么有 approved,要么在待批准清单里")
    void everySampleIsApprovedOrPending() {
        for (String name : SampleRepo.allSampleNames()) {
            boolean hasApproved = Files.exists(SampleRepo.approved(name));
            boolean isPending = SampleRepo.PENDING_APPROVAL.contains(name);
            assertTrue(hasApproved || isPending, () -> String.format(
                    "样本【%s】既没有 approved 文件,也不在 SampleRepo.PENDING_APPROVAL 里。"
                  + "漏批准的样本不允许被静默跳过。", name));
        }
    }

    @Test
    @DisplayName("守卫:待批准清单里的样本必须确实存在且确实还没批准")
    void pendingListStaysHonest() {
        List<String> all = SampleRepo.allSampleNames();
        for (String name : SampleRepo.PENDING_APPROVAL) {
            assertTrue(all.contains(name), () -> String.format(
                    "PENDING_APPROVAL 里的【%s】没有对应的 request 文件,名字写错了或样本被删了。", name));
            assertFalse(Files.exists(SampleRepo.approved(name)), () -> String.format(
                    "【%s】已经有 approved 文件了,请把它从 SampleRepo.PENDING_APPROVAL 里删掉,"
                  + "让它纳入 golden master 回放。", name));
        }
    }

    @Test
    @DisplayName("守卫:已批准样本不能为空")
    void approvedSetIsNotEmpty() {
        assertFalse(SampleRepo.approvedSampleNames().isEmpty(),
                "扫不到任何已批准样本。samples 目录路径不对,或 approved 文件被误删了。");
    }
}
