package com.example.freight.golden;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

/**
 * 偏远附加(按省份查表)新路径。
 *
 * 期望值来自需求翻译的例子,不是来自程序输出 —— 新路径没有改动前的行为可以当基线,
 * 用 golden master 去「批准」它跑出来的结果,只会把可能的错固化下来。
 */
@DisplayName("偏远附加:模板配了偏远省份表时走新路径")
class FreightRemoteSurchargeTest {

    private static final String SAMPLE = "首重续重-新疆-vip";

    @Test
    @DisplayName("模板 1032 + 新疆 + 3.2kg + vip → fee = 26")
    void remoteSurchargeMatchesSpecExample() {
        JsonNode result = FreightCalcHarness.replaySample(SAMPLE);

        // 落盘供人工审 items 明细;明细确认后改名为 .approved.json 并从 PENDING_APPROVAL 删除。
        SampleRepo.writeUtf8(SampleRepo.received(SAMPLE), JsonNormalizer.normalize(result));

        JsonNode fee = result.get("fee");
        assertNotNull(fee, "返回值里没有 fee 字段");
        assertEquals(0, fee.decimalValue().compareTo(new BigDecimal("26")), () -> String.format(
                "需求例子要求 fee=26,实际 %s。完整输出见 %s。", fee, SampleRepo.received(SAMPLE)));
        // items 明细暂不断言:需求只给了总额。确认拆分后在这里补断言,或转成 approved 样本。
    }
}
```

用 `compareTo` 而不是直接 `assertEquals(BigDecimal)`,是因为后者连 scale 一起比,`26` 和 `26.0` 会误报。

